SELECT 
FROM conversation_node n
JOIN conversation c ON c.id = n.conversation_id
WHERE n.conversation_id = #{conversationId}
  AND n.turn_id = #{turnId}
  AND c.user_id = #{userId}
  AND c.is_deleted = 0
ORDER BY n.id

SELECT 
FROM conversation_node n
WHERE n.conversation_id = #{conversationId}
  AND n.turn_id = #{turnId}
ORDER BY n.id

SELECT 
FROM conversation_node n
JOIN conversation c ON c.id = n.conversation_id
WHERE n.conversation_id = #{conversationId}
  AND n.turn_id < #{currentTurnId}
  AND c.user_id = #{userId}
  AND c.is_deleted = 0
  AND n.type = 'TOOL_CALL'
ORDER BY n.turn_id, n.round_no, n.call_index, n.id

SELECT 
FROM conversation_node n
JOIN conversation c ON c.id = n.conversation_id
WHERE n.conversation_id = #{conversationId}
  AND n.turn_id = #{targetTurnId}
  AND n.aggr_key = #{aggrKey}
  AND c.user_id = #{userId}
  AND c.is_deleted = 0
ORDER BY n.id
